import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score

def auc_pair(y_true, y_score):
    return roc_auc_score(y_true, y_score), average_precision_score(y_true, y_score)

import torch
import torch.nn as nn

torch.manual_seed(0)

def build(init_name):
    layers = []
    for _ in range(20):
        lin = nn.Linear(128, 128)
        if init_name == 'kaiming':
            nn.init.kaiming_normal_(lin.weight, nonlinearity='relu')
        else:
            nn.init.xavier_uniform_(lin.weight)
        nn.init.zeros_(lin.bias)
        layers += [lin, nn.ReLU()]
    return nn.Sequential(*layers)

x = torch.randn(64, 128)
for name in ['kaiming', 'xavier']:
    net = build(name).eval()
    with torch.no_grad():
        print(name, net(x).std().item())

import torch
import torch.nn as nn

x = torch.tensor([-2.0, -1.0, 0.0, 1.0, 2.0], requires_grad=True)

for name, fn in [('relu', torch.relu), ('gelu', nn.functional.gelu)]:
    if x.grad is not None:
        x.grad.zero_()
    fn(x).sum().backward()
    print(name, [round(v, 4) for v in x.grad.tolist()])
